// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount); // admissible: amount within balance
        Reverter r = new Reverter(); // receiver that refuses ether
        vm.prank(address(this)); // test contract is owner
        bool ok;
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "sendTo to a refusing receiver must revert");
    }
}

contract Reverter { fallback() external payable { revert(); } }
